import {
  getChaosSpawnNatures,
  getCorruptionLoss,
  getReducedCorruption,
  resolveMutationNature,
} from "../../../functions/mutants-handbook/rules";
import type { WfrpActor, WfrpMutationItem } from "../../../types/foundry";
import type { CharacteristicBonuses, MutationNature } from "../../../types/mutants-handbook";
import { MODULE_ID } from "../../constants";
import { CHAOS_SPAWN_FLAG } from "./constants";
import { getMutationCounts, restoreRetiredMutations, retireSkinwalkerMutations } from "./documents";
import { spendResilience } from "./dialogs";
import { formatMutationMessage, postMutationMessage, warnAboutMutation } from "./messages";
import {
  getPendingCorruption,
  pendingMutationPath,
  readPendingMutation,
  removePendingCorruptionPath,
  type PendingMutationDrop,
} from "./pending-corruption";
import { updateActor } from "./updates";

function bonuses(actor: WfrpActor): CharacteristicBonuses {
  return {
    toughness: Number(actor.system.characteristics.t.bonus),
    willpower: Number(actor.system.characteristics.wp.bonus),
  };
}

function corruptionLoss(actor: WfrpActor, nature: MutationNature): number {
  return getCorruptionLoss(nature, bonuses(actor));
}

function abortDrop(options: Record<string, unknown>): false {
  options["abortItemCreation"] = true;
  options["mutationAcquisitionCancelled"] = true;
  return false;
}

function pendingMatchesItem(item: WfrpMutationItem, pending: PendingMutationDrop): boolean {
  return (
    item.name === pending.mutationName &&
    resolveMutationNature(item.system.mutationType.value) === pending.nature
  );
}

export async function preparePendingMutationDrop(
  item: WfrpMutationItem,
  actor: WfrpActor,
  options: Record<string, unknown>,
): Promise<boolean> {
  const pending = readPendingMutation(item);
  if (!pending) return true;

  const expected = getPendingCorruption(actor);
  if (pending.actorUuid !== actor.uuid) {
    warnAboutMutation(`${item.name} was rolled for another Actor and cannot be acquired here.`);
    return abortDrop(options);
  }
  if (!pendingMatchesItem(item, pending)) {
    warnAboutMutation(`${item.name} no longer matches the rolled mutation card.`);
    return abortDrop(options);
  }
  if (expected?.kind !== "mutation" || expected.token !== pending.token) {
    warnAboutMutation(`${item.name} is no longer awaiting acquisition for ${actor.name}.`);
    return abortDrop(options);
  }

  const resilience = Number(actor.system.status.resilience.value);
  if (resilience > 0 && (await spendResilience(actor.name, item.name))) {
    const loss = corruptionLoss(actor, pending.nature);
    await updateActor(actor, {
      [removePendingCorruptionPath]: null,
      "system.status.corruption.value": getReducedCorruption(
        Number(actor.system.status.corruption.value),
        loss,
      ),
      "system.status.resilience.value": Math.max(0, resilience - 1),
    });
    item.updateSource?.({ [pendingMutationPath]: null });
    await postMutationMessage(
      formatMutationMessage("Resisted", {
        loss,
        mutation: item.name,
        name: actor.name,
      }),
    );
    return abortDrop(options);
  }

  options["mutationAcquisitionCanReroll"] = false;
  options["mutationAcquisitionHandlesChimeranRetirement"] = true;
  return true;
}

async function announceChaosSpawn(
  actor: WfrpActor,
  exceededNatures: MutationNature[],
): Promise<void> {
  for (const nature of exceededNatures) {
    const message = formatMutationMessage("ChaosSpawn", {
      bonus: nature === "physical" ? "Toughness Bonus" : "Willpower Bonus",
      name: actor.name,
      nature,
    });
    warnAboutMutation(message);
    await postMutationMessage(message);
  }
}

export async function finalizePendingMutationDrop(mutation: WfrpMutationItem): Promise<boolean> {
  const pending = readPendingMutation(mutation);
  const actor = mutation.actor;
  if (!pending || !actor) return false;

  const expected = getPendingCorruption(actor);
  if (expected?.kind !== "mutation" || expected.token !== pending.token) {
    throw new Error(`${mutation.name} is not the pending mutation for ${actor.name}.`);
  }
  if (!pendingMatchesItem(mutation, pending)) {
    throw new Error(`${mutation.name} no longer matches its pending mutation result.`);
  }

  const loss = corruptionLoss(actor, pending.nature);
  let retiredSkinwalkerIds: string[] = [];
  try {
    if (mutation.name.trim().toLowerCase() === "chimeran curse") {
      retiredSkinwalkerIds = await retireSkinwalkerMutations(actor);
    }
    const exceededNatures = getChaosSpawnNatures(getMutationCounts(actor), bonuses(actor));
    await updateActor(actor, {
      [removePendingCorruptionPath]: null,
      ...(exceededNatures.length > 0 ? { [`flags.${MODULE_ID}.${CHAOS_SPAWN_FLAG}`]: true } : {}),
      "system.status.corruption.value": getReducedCorruption(
        Number(actor.system.status.corruption.value),
        loss,
      ),
    });

    try {
      await mutation.update?.({ [pendingMutationPath]: null }, { skipMutationAcquisition: true });
    } catch (error) {
      console.warn(`${mutation.name}: could not clear its completed mutation-drop marker.`, error);
    }

    await postMutationMessage(
      formatMutationMessage("Gained", {
        loss,
        mutation: mutation.name,
        name: actor.name,
      }),
    );
    await announceChaosSpawn(actor, exceededNatures);
    return true;
  } catch (error) {
    const rollbackErrors: unknown[] = [error];
    try {
      await restoreRetiredMutations(actor, retiredSkinwalkerIds);
    } catch (rollbackError) {
      rollbackErrors.push(rollbackError);
    }
    try {
      await actor.deleteEmbeddedDocuments("Item", [mutation.id]);
    } catch (rollbackError) {
      rollbackErrors.push(rollbackError);
    }
    if (rollbackErrors.length > 1) {
      throw new AggregateError(
        rollbackErrors,
        `Failed to roll back mutation acquisition for ${actor.name}.`,
        { cause: error },
      );
    }
    throw error;
  }
}
