import type { MutationForm } from "../../../../functions/mutants-handbook/actions";
import { MODULE_ID } from "../../../constants";
import { isRecord } from "./documents";
import { mutationNumber, mutationScriptData } from "./effect-helpers";
import type { MutationActionActor } from "./types";

const FORM_ITEM_UUIDS: Readonly<Record<string, string>> = {
  Contortionist: "Compendium.wfrp4e-core.items.Item.TaYriYcJkFuIdBKp",
  Frenzy: "Compendium.wfrp4e-core.items.Item.hXcfygzujgyMN1uI",
  Painless: "Compendium.wfrp4e-core.items.Item.wMwSRDmgiF2IdCJr",
};

function syntheticItem(name: string, type: "talent" | "trait", form: MutationForm) {
  const match = /^(.*) (\d+)$/.exec(name);
  const baseName = match?.[1] ?? name;
  const specification = match?.[2] ?? (baseName === "Fear" ? "1" : "");
  return {
    effects: [],
    flags: { [MODULE_ID]: { automationPhase: "mutation-phase-5", mutationForm: form } },
    img: "systems/wfrp4e/icons/blank.png",
    name: baseName,
    system: {
      description: {
        value: `<p>Temporary ${name} benefit supplied by the active Mutant's Handbook form.</p>`,
      },
      specification: { value: specification },
    },
    type,
  };
}

async function itemData(name: string, type: "talent" | "trait", form: MutationForm) {
  const resolver = Reflect.get(globalThis, "fromUuid") as
    | ((uuid: string) => Promise<{ toObject?: () => Record<string, unknown> } | undefined>)
    | undefined;
  const source = FORM_ITEM_UUIDS[name] ? await resolver?.(FORM_ITEM_UUIDS[name]) : undefined;
  const data = source?.toObject?.() ?? syntheticItem(name, type, form);
  delete data["_id"];
  const flags = isRecord(data["flags"]) ? data["flags"] : {};
  data["flags"] = flags;
  flags[MODULE_ID] = { automationPhase: "mutation-phase-5", mutationForm: form };
  return data;
}

export async function createFormItems(
  actor: MutationActionActor,
  form: MutationForm,
  items: readonly [string, "talent" | "trait"][],
): Promise<void> {
  if (!items.length) return;
  await actor.createEmbeddedDocuments?.(
    "Item",
    await Promise.all(items.map(([name, type]) => itemData(name, type, form))),
  );
}

function acquisitionGrantData(
  acquisition: Record<string, unknown>,
): Array<Record<string, unknown>> {
  return Array.isArray(acquisition["grants"]) ? acquisition["grants"].filter(isRecord) : [];
}

export async function createAcquisitionFormGrants(
  actor: MutationActionActor,
  form: MutationForm,
  acquisition: Record<string, unknown>,
): Promise<void> {
  const resolver = Reflect.get(globalThis, "fromUuid") as
    | ((uuid: string) => Promise<{ toObject?: () => Record<string, unknown> } | undefined>)
    | undefined;
  const documents = [];
  for (const grant of acquisitionGrantData(acquisition)) {
    const source =
      typeof grant["sourceUuid"] === "string" ? await resolver?.(grant["sourceUuid"]) : undefined;
    const data = source?.toObject?.();
    if (!data) continue;
    delete data["_id"];
    const flags = isRecord(data["flags"]) ? data["flags"] : {};
    data["flags"] = flags;
    flags[MODULE_ID] = { automationPhase: "mutation-phase-5", mutationForm: form };
    documents.push(data);
  }
  if (documents.length) await actor.createEmbeddedDocuments?.("Item", documents);
}

export function acquisitionFormChanges(
  acquisition: Record<string, unknown>,
): Record<string, unknown>[] {
  const modifiers = Array.isArray(acquisition["modifiers"])
    ? acquisition["modifiers"].filter(isRecord)
    : [];
  return modifiers.flatMap((modifier) => {
    const value = mutationNumber(modifier["value"], Number.NaN);
    if (!Number.isFinite(value)) return [];
    if (modifier["kind"] === "characteristic" && typeof modifier["characteristic"] === "string") {
      return [
        {
          key: `system.characteristics.${modifier["characteristic"]}.modifier`,
          mode: 2,
          priority: null,
          value: String(value),
        },
      ];
    }
    if (modifier["kind"] === "move") {
      return [{ key: "system.details.move.value", mode: 2, priority: null, value: String(value) }];
    }
    return [];
  });
}

export function acquisitionFormTestScript(
  acquisition: Record<string, unknown>,
): Record<string, unknown> | undefined {
  const modifiers = Array.isArray(acquisition["modifiers"])
    ? acquisition["modifiers"].filter(
        (modifier) => isRecord(modifier) && modifier["kind"] === "test",
      )
    : [];
  if (!modifiers.length) return undefined;
  const stored = JSON.stringify(modifiers);
  return mutationScriptData(
    "Resolve Mutant's Handbook form",
    "dialog",
    `const modifiers = ${stored};\nconst skillName = args.skill?.name ?? args.test?.item?.name ?? "";\nconst characteristic = args.characteristic ?? args.test?.characteristicKey;\nfor (const modifier of modifiers) {\n  const matchesSkill = (modifier.skills ?? []).some(name => skillName === name || skillName.startsWith(name + " ("));\n  const matchesCharacteristic = (modifier.characteristics ?? []).includes(characteristic);\n  if (!matchesSkill && !matchesCharacteristic) continue;\n  const current = Number(args.fields.modifier);\n  const next = current + Number(modifier.value);\n  if (Number.isFinite(next)) args.fields.modifier = next;\n}`,
  );
}
