import type {
  MutationActionDefinition,
  MutationCompanion,
} from "../../../../functions/mutants-handbook/actions";
import { MODULE_ID } from "../../../constants";
import { activeMutationItems, isRecord, mutationAcquisition } from "./documents";
import type { MutationActionActor, MutationActionItem } from "./types";

type CreatedActor = MutationActionActor & { id?: string; uuid?: string };

function selected(acquisition: Record<string, unknown>, key: string): string {
  const selections = isRecord(acquisition["selections"]) ? acquisition["selections"] : {};
  const value = selections[key];
  return Array.isArray(value) ? String(value[0] ?? "") : String(value ?? "");
}

function title(value: string): string {
  return value
    .split("-")
    .filter(Boolean)
    .map((word) => `${word[0]?.toUpperCase() ?? ""}${word.slice(1)}`)
    .join(" ");
}

function setCharacteristic(system: Record<string, unknown>, key: string, value: number): void {
  const characteristics = isRecord(system["characteristics"]) ? system["characteristics"] : {};
  system["characteristics"] = characteristics;
  const characteristic = isRecord(characteristics[key]) ? characteristics[key] : {};
  characteristics[key] = characteristic;
  characteristic["initial"] = value;
  characteristic["advances"] = 0;
  characteristic["modifier"] = 0;
  characteristic["value"] = value;
}

function companionNotes(acquisition: Record<string, unknown>, prefix: string): string {
  const rows = ["personality", "motivation", "short-ambition", "long-ambition"].flatMap((key) => {
    const value = selected(acquisition, `${prefix}-${key}`);
    return value ? [`<p><strong>${title(key)}:</strong> ${value}</p>`] : [];
  });
  return rows.join("");
}

function basicCompanion(
  actor: MutationActionActor,
  companion: MutationCompanion,
  acquisition: Record<string, unknown>,
): Record<string, unknown> {
  const hostName = actor.name ?? "Mutant";
  if (companion === "spectral-companion") {
    const kind = selected(acquisition, "companion-type") || "ghost";
    const name = selected(acquisition, "companion-name") || `${hostName}'s ${title(kind)}`;
    return {
      flags: {},
      img: "icons/magic/death/undead-ghost-scream-teal.webp",
      name,
      system: { details: { notes: { value: companionNotes(acquisition, "companion") } } },
      type: "creature",
    };
  }
  const source = actor.toObject?.() ?? {};
  delete source["_id"];
  source["effects"] = [];
  source["flags"] = {};
  source["folder"] = null;
  source["items"] = [];
  source["type"] = "creature";
  const system = isRecord(source["system"]) ? source["system"] : {};
  source["system"] = system;
  if (companion === "bodysnatcher-drone") {
    source["name"] = `${hostName}'s Bodysnatcher Drone`;
    for (const [key, value] of Object.entries({
      ag: 30,
      bs: 0,
      dex: 0,
      fel: 0,
      i: 0,
      int: 0,
      s: 0,
      t: 0,
      wp: 0,
      ws: 30,
    })) {
      setCharacteristic(system, key, value);
    }
    system["details"] = {
      ...(isRecord(system["details"]) ? system["details"] : {}),
      move: { value: 2 },
      size: { value: "tiny" },
    };
    system["status"] = {
      ...(isRecord(system["status"]) ? system["status"] : {}),
      wounds: { max: 1, value: 1 },
    };
    source["items"] = [
      {
        name: "Dodge",
        type: "skill",
        system: { advances: { value: 0 }, characteristic: { value: "ag" } },
      },
      {
        name: "Melee (Grapple)",
        type: "skill",
        system: { advances: { value: 0 }, characteristic: { value: "ws" } },
      },
      {
        name: "Stealth",
        type: "skill",
        system: { advances: { value: 10 }, characteristic: { value: "ag" } },
      },
      {
        name: "Wallcrawler",
        type: "trait",
        system: {
          description: { value: "<p>May traverse walls and ceilings.</p>" },
          specification: { value: "" },
        },
      },
    ];
    return source;
  }
  source["name"] = `${hostName}'s Vestigial Twin`;
  for (const key of ["ws", "bs", "s", "t", "ag", "fel"]) {
    const penalty =
      key === "t" || key === "fel" ? 20 : key === "ag" ? Number.POSITIVE_INFINITY : 30;
    const current = Number(actor.system?.characteristics?.[key]?.value) || 0;
    setCharacteristic(system, key, Number.isFinite(penalty) ? Math.max(0, current - penalty) : 0);
  }
  system["details"] = {
    ...(isRecord(system["details"]) ? system["details"] : {}),
    move: { value: 0 },
    notes: { value: companionNotes(acquisition, "twin") },
  };
  system["status"] = {
    ...(isRecord(system["status"]) ? system["status"] : {}),
    fate: { max: 0, value: 0 },
    resilience: { max: 0, value: 0 },
  };
  return source;
}

function symbioticTwin(actor: MutationActionActor, acquisition: Record<string, unknown>) {
  const data = actor.toObject?.() ?? {};
  delete data["_id"];
  data["name"] = `${actor.name ?? "Mutant"}'s Symbiotic Twin`;
  if (Array.isArray(data["items"])) {
    data["items"] = data["items"].filter((item) => {
      if (!isRecord(item) || !isRecord(item["flags"])) return true;
      const moduleFlags = item["flags"][MODULE_ID];
      if (!isRecord(moduleFlags) || !isRecord(moduleFlags["mutationAction"])) return true;
      return moduleFlags["mutationAction"]["actionId"] !== "symbiotic-twin-manifest";
    });
  }
  const system = isRecord(data["system"]) ? data["system"] : {};
  data["system"] = system;
  const details = isRecord(system["details"]) ? system["details"] : {};
  system["details"] = details;
  details["notes"] = { value: companionNotes(acquisition, "twin") };
  return data;
}

interface CompanionLink {
  mutationItemId?: string;
  uuid: string;
}

function companionLinks(actor: MutationActionActor, companion: MutationCompanion): CompanionLink[] {
  const links = actor.flags?.[MODULE_ID]?.["mutationCompanions"];
  const stored = isRecord(links) ? links[companion] : undefined;
  if (typeof stored === "string") return [{ uuid: stored }];
  if (!Array.isArray(stored)) return [];
  return stored.flatMap((entry) =>
    isRecord(entry) && typeof entry["uuid"] === "string"
      ? [
          {
            mutationItemId:
              typeof entry["mutationItemId"] === "string" ? entry["mutationItemId"] : undefined,
            uuid: entry["uuid"],
          },
        ]
      : [],
  );
}

async function liveCompanionLinks(actor: MutationActionActor, companion: MutationCompanion) {
  const links = companionLinks(actor, companion);
  const resolver = Reflect.get(globalThis, "fromUuid") as
    | ((uuid: string) => Promise<unknown>)
    | undefined;
  if (!resolver) return links;
  const resolved = await Promise.all(
    links.map(async (link) => ((await resolver(link.uuid)) ? link : undefined)),
  );
  return resolved.filter((link): link is CompanionLink => link !== undefined);
}

function nextMutationItem(items: MutationActionItem[], links: CompanionLink[]) {
  const linked = new Set(
    links.flatMap((link) => (link.mutationItemId ? [link.mutationItemId] : [])),
  );
  return items.find((item) => !item.id || !linked.has(item.id)) ?? items[links.length];
}

export async function createMutationCompanion(
  companion: MutationCompanion,
  actor: MutationActionActor,
  action: MutationActionDefinition,
): Promise<void> {
  const mutations = activeMutationItems(actor, action.mutationId);
  const links = await liveCompanionLinks(actor, companion);
  if (!mutations.length || links.length >= mutations.length) return;
  const mutation = nextMutationItem(mutations, links);
  const acquisition = mutationAcquisition(mutation);
  const data =
    companion === "symbiotic-twin"
      ? symbioticTwin(actor, acquisition)
      : basicCompanion(actor, companion, acquisition);
  const flags = isRecord(data["flags"]) ? data["flags"] : {};
  data["flags"] = flags;
  flags[MODULE_ID] = {
    automationPhase: "mutation-phase-5",
    mutationCompanion: {
      hostUuid: actor.uuid ?? actor.id,
      kind: companion,
      mutationId: action.mutationId,
    },
  };
  const ActorClass = Reflect.get(globalThis, "Actor") as
    | { create?: (data: Record<string, unknown>) => Promise<CreatedActor | undefined> }
    | undefined;
  const created = await ActorClass?.create?.(data);
  const uuid = created?.uuid ?? created?.id;
  if (!uuid) return;
  await actor.update?.({
    [`flags.${MODULE_ID}.mutationCompanions.${companion}`]: [
      ...links,
      { mutationItemId: mutation?.id, uuid },
    ],
  });
  if (companion === "symbiotic-twin") {
    await actor.update?.({ [`flags.${MODULE_ID}.mutationTwinUuid`]: uuid });
    await created?.update?.({ [`flags.${MODULE_ID}.mutationTwinUuid`]: actor.uuid ?? actor.id });
  }
}

const syncingTwins = new Set<string>();

export function registerMutationCompanionHooks(): void {
  Hooks.on("updateActor", (actorValue, changes, _options, userId) => {
    const currentGame = Reflect.get(globalThis, "game") as { user?: { id?: string } } | undefined;
    if (typeof userId === "string" && currentGame?.user?.id !== userId) return;
    if (!isRecord(actorValue) || !isRecord(changes)) return;
    const actor = actorValue as MutationActionActor;
    const actorUuid = actor.uuid ?? actor.id;
    const moduleFlags = actor.flags?.[MODULE_ID];
    const twinUuid = moduleFlags?.["mutationTwinUuid"];
    const nestedSystem = isRecord(changes["system"]) ? changes["system"] : undefined;
    const nestedStatus = isRecord(nestedSystem?.["status"]) ? nestedSystem["status"] : undefined;
    const nestedWounds = isRecord(nestedStatus?.["wounds"]) ? nestedStatus["wounds"] : undefined;
    const wounds = changes["system.status.wounds.value"] ?? nestedWounds?.["value"];
    if (
      typeof actorUuid !== "string" ||
      typeof twinUuid !== "string" ||
      !Number.isFinite(Number(wounds)) ||
      syncingTwins.has(actorUuid)
    )
      return;
    const resolver = Reflect.get(globalThis, "fromUuid") as
      | ((uuid: string) => Promise<CreatedActor | undefined>)
      | undefined;
    syncingTwins.add(twinUuid);
    void resolver?.(twinUuid)
      .then((twin) => twin?.update?.({ "system.status.wounds.value": Number(wounds) }))
      .finally(() => syncingTwins.delete(twinUuid));
  });
}
