import type { MutationActionDefinition } from "./types.ts";
import { MUTATION_ACTIONS_A_F } from "./catalog/a-f.ts";
import { MUTATION_ACTIONS_ADDITIONAL } from "./catalog/additional.ts";
import { MUTATION_ACTIONS_CHAINED } from "./catalog/chained.ts";
import { MUTATION_ACTIONS_G_O } from "./catalog/g-o.ts";
import { MUTATION_ACTIONS_P_S } from "./catalog/p-s.ts";
import { MUTATION_ACTIONS_PHASE_FOUR } from "./catalog/phase-four.ts";
import { MUTATION_ACTIONS_PHASE_FIVE } from "./catalog/phase-five.ts";
import { MUTATION_ACTIONS_T_W } from "./catalog/t-w.ts";

export const MUTATION_ACTIONS: readonly MutationActionDefinition[] = Object.freeze([
  ...MUTATION_ACTIONS_A_F,
  ...MUTATION_ACTIONS_G_O,
  ...MUTATION_ACTIONS_P_S,
  ...MUTATION_ACTIONS_T_W,
  ...MUTATION_ACTIONS_CHAINED,
  ...MUTATION_ACTIONS_ADDITIONAL,
  ...MUTATION_ACTIONS_PHASE_FOUR,
  ...MUTATION_ACTIONS_PHASE_FIVE,
]);

export const MUTATION_ACTIONS_BY_ID: ReadonlyMap<string, MutationActionDefinition> = new Map(
  MUTATION_ACTIONS.map((action) => [action.id, action]),
);

const actionsByMutation = new Map<string, MutationActionDefinition[]>();
for (const action of MUTATION_ACTIONS) {
  const actions = actionsByMutation.get(action.mutationId) ?? [];
  actions.push(action);
  actionsByMutation.set(action.mutationId, actions);
}

export const MUTATION_ACTIONS_BY_MUTATION_ID: ReadonlyMap<
  string,
  readonly MutationActionDefinition[]
> = new Map(
  [...actionsByMutation].map(([mutationId, actions]) => [mutationId, Object.freeze(actions)]),
);

export function getMutationAction(id: string): MutationActionDefinition | undefined {
  return MUTATION_ACTIONS_BY_ID.get(id);
}

export function getMutationActionsForMutation(
  mutationId: string,
): readonly MutationActionDefinition[] {
  return MUTATION_ACTIONS_BY_MUTATION_ID.get(mutationId) ?? [];
}
