import type { WfrpActor, WfrpMutationItem } from "../../../../types/foundry";
import { MODULE_ID } from "../../../constants";
import {
  getGrantOwnership,
  getSkillGrantLedger,
  type MutationSkillGrantLedger,
  type MutationSkillGrantOwner,
} from "./grant-data";

interface RankedSkillSignatureData {
  appliedRanks: number;
  legacy: boolean;
  managed: boolean;
  owners: MutationSkillGrantOwner[];
}

export function actorItems(actor: WfrpActor): WfrpMutationItem[] {
  return Array.from(actor.items);
}

export function isItem(value: unknown): value is WfrpMutationItem {
  if (typeof value !== "object" || value === null) return false;
  const item = value as Partial<WfrpMutationItem>;
  return (
    typeof item.name === "string" &&
    typeof item.type === "string" &&
    typeof item.toObject === "function"
  );
}

function itemAdvances(item: WfrpMutationItem): number {
  const system = item.toObject()["system"];
  if (typeof system !== "object" || system === null) return 0;
  const advances = (system as Record<string, unknown>)["advances"];
  if (typeof advances !== "object" || advances === null) return 0;
  const value = Number((advances as Record<string, unknown>)["value"]);
  return Number.isFinite(value) ? value : 0;
}

export function rankedSignatureData(item: WfrpMutationItem): RankedSkillSignatureData | undefined {
  const ledger = getSkillGrantLedger(item);
  if (ledger) return { ...ledger, legacy: false };

  const ownership = getGrantOwnership(item);
  if (!ownership) return undefined;
  let signature: unknown;
  try {
    signature = JSON.parse(ownership.signature);
  } catch {
    return undefined;
  }
  if (typeof signature !== "object" || signature === null) return undefined;
  const values = signature as Record<string, unknown>;
  if (values["stack"] !== "rank" || values["type"] !== "skill") return undefined;
  const ranks = Number(values["ranks"]);
  if (!Number.isFinite(ranks) || ranks <= 0) return undefined;
  const owners = ownership.owners.map((owner) => ({
    ...owner,
    ranks,
    signature: ownership.signature,
    sourceUuid: ownership.sourceUuid,
  }));
  return {
    appliedRanks: ranks * owners.length,
    legacy: true,
    managed: ownership.managed,
    owners,
  };
}

export function baseAdvances(item: WfrpMutationItem, desiredRanks?: number): number {
  const advances = itemAdvances(item);
  const ranked = rankedSignatureData(item);
  if (!ranked) return Math.max(0, advances);

  // A pre-ledger ranked Skill could have absorbed another Skill through WFRP's merge hook
  // without receiving that attempted Item's ownership flag. During the one-time conversion,
  // treat ranks already present for active mutations as automation ranks so they are not added
  // a second time. Released versions did not create ranked Skills, but this also safely repairs
  // worlds that exercised an in-development build.
  const appliedRanks =
    ranked.legacy && desiredRanks !== undefined
      ? Math.max(ranked.appliedRanks, Math.min(desiredRanks, advances))
      : ranked.appliedRanks;
  return Math.max(0, advances - appliedRanks);
}

export function isAutomationManaged(item: WfrpMutationItem): boolean {
  return rankedSignatureData(item)?.managed === true;
}

export function canonicalPriority(item: WfrpMutationItem): number {
  const ranked = rankedSignatureData(item);
  if (ranked?.managed === false) return 0;
  if (!ranked) return 1;
  return 2;
}

export function setAdvances(data: Record<string, unknown>, advances: number): void {
  const system =
    typeof data["system"] === "object" && data["system"] !== null
      ? (data["system"] as Record<string, unknown>)
      : {};
  data["system"] = system;
  const current = system["advances"];
  const values =
    typeof current === "object" && current !== null ? (current as Record<string, unknown>) : {};
  system["advances"] = values;
  values["value"] = advances;
}

export function setLedgerFlag(
  data: Record<string, unknown>,
  ledger: MutationSkillGrantLedger,
): void {
  const flags =
    typeof data["flags"] === "object" && data["flags"] !== null
      ? (data["flags"] as Record<string, unknown>)
      : {};
  data["flags"] = flags;
  const moduleFlags =
    typeof flags[MODULE_ID] === "object" && flags[MODULE_ID] !== null
      ? (flags[MODULE_ID] as Record<string, unknown>)
      : {};
  flags[MODULE_ID] = moduleFlags;
  moduleFlags["mutationSkillGrant"] = ledger;
}

export async function updateItem(
  actor: WfrpActor,
  item: WfrpMutationItem,
  changes: Record<string, unknown>,
): Promise<void> {
  const options = { skipExperienceChecks: true };
  if (item.update) await item.update(changes, options);
  else await actor.updateEmbeddedDocuments("Item", [{ _id: item.id, ...changes }], options);
}

export function clearLedgerChanges(advances: number): Record<string, unknown> {
  return {
    "system.advances.value": advances,
    [`flags.${MODULE_ID}.-=mutationSkillGrant`]: null,
  };
}
