import type { WfrpActor, WfrpMutationItem } from "../../../../../types/foundry";
import type {
  MutationAutomationDefinition,
  MutationGrantDefinition,
} from "../../../../../types/mutants-handbook";
import { MODULE_ID } from "../../../../constants";
import { MUTATION_RETIRED_FLAG, POSSESSION_REMOVED_FLAG } from "../../constants";
import {
  getGrantOwnership,
  getLegacyGrantOwners,
  grantDataMatches,
  hasMatchingSourceIdentity,
  isLegacyManagedGrant,
  type MutationGrantOwner,
  type MutationGrantOwnership,
} from "../grant-data";

export function actorItems(actor: WfrpActor): WfrpMutationItem[] {
  return Array.from(actor.items);
}

export function isActor(value: unknown): value is WfrpActor {
  if (typeof value !== "object" || value === null) return false;
  const actor = value as Partial<WfrpActor>;
  return (
    typeof actor.createEmbeddedDocuments === "function" &&
    typeof actor.deleteEmbeddedDocuments === "function" &&
    actor.items !== undefined
  );
}

export function isItem(value: unknown): value is WfrpMutationItem {
  if (typeof value !== "object" || value === null) return false;
  const item = value as Partial<WfrpMutationItem>;
  return (
    typeof item.name === "string" &&
    typeof item.type === "string" &&
    typeof item.toObject === "function"
  );
}

export function mutationAutomation(
  item: WfrpMutationItem,
): MutationAutomationDefinition | undefined {
  const value = item.flags?.[MODULE_ID]?.["mutationAutomation"];
  if (typeof value !== "object" || value === null) return undefined;

  const definition = value as Partial<MutationAutomationDefinition>;
  if (
    typeof definition.definitionId !== "string" ||
    typeof definition.version !== "number" ||
    (definition.grants !== undefined && !Array.isArray(definition.grants))
  ) {
    return undefined;
  }

  return value as MutationAutomationDefinition;
}

export function isPossessionRemoved(item: WfrpMutationItem): boolean {
  return item.getFlag(MODULE_ID, POSSESSION_REMOVED_FLAG) === true;
}

export function isMutationRetired(item: WfrpMutationItem): boolean {
  return isPossessionRemoved(item) || item.getFlag(MODULE_ID, MUTATION_RETIRED_FLAG) === true;
}

export function isFirstAcquisition(
  actor: WfrpActor,
  mutation: WfrpMutationItem,
  definitionId: string,
): boolean {
  const matching = actorItems(actor)
    .filter(
      (item) =>
        item.type === "mutation" &&
        !isMutationRetired(item) &&
        mutationAutomation(item)?.definitionId === definitionId,
    )
    .sort((left, right) => left.id.localeCompare(right.id));
  return matching[0]?.id === mutation.id;
}

export async function updateItem(
  actor: WfrpActor,
  item: WfrpMutationItem,
  changes: Record<string, unknown>,
): Promise<void> {
  if (item.update) {
    await item.update(changes);
  } else {
    await actor.updateEmbeddedDocuments("Item", [{ _id: item.id, ...changes }]);
  }
}

export function ownershipForCandidate(
  item: WfrpMutationItem,
  grant: MutationGrantDefinition,
  signature: string,
  owner: MutationGrantOwner,
): MutationGrantOwnership {
  const current = getGrantOwnership(item);
  const legacyOwners = getLegacyGrantOwners(item).map((ownerId) => ({
    grantKey: "legacy",
    ownerId,
  }));
  const owners = [...(current?.owners ?? legacyOwners)];

  if (
    !owners.some((entry) => entry.ownerId === owner.ownerId && entry.grantKey === owner.grantKey)
  ) {
    owners.push(owner);
  }

  return {
    managed: current?.managed ?? isLegacyManagedGrant(item),
    owners,
    signature,
    sourceUuid: grant.sourceUuid,
    version: 2,
  };
}

export function findGrantCandidate(
  actor: WfrpActor,
  source: WfrpMutationItem,
  grant: MutationGrantDefinition,
  signature: string,
  owner: MutationGrantOwner,
): WfrpMutationItem | undefined {
  const matching = actorItems(actor)
    .filter((item) => grantDataMatches(item, source, grant))
    .sort((left, right) => left.id.localeCompare(right.id));
  const owned = matching.find((item) => {
    const ownership = getGrantOwnership(item);
    return (
      ownership?.signature === signature &&
      ownership.owners.some(
        (entry) => entry.ownerId === owner.ownerId && entry.grantKey === owner.grantKey,
      )
    );
  });
  if ((grant.stack ?? "singleton") === "rank") {
    return owned ?? matching.find((item) => getLegacyGrantOwners(item).includes(owner.ownerId));
  }

  const canonical = matching
    .filter((item) => {
      const ownership = getGrantOwnership(item);
      return (
        ownership?.signature === signature ||
        (!ownership &&
          getLegacyGrantOwners(item).length === 0 &&
          (grant.type === "skill" || hasMatchingSourceIdentity(item, grant.sourceUuid)))
      );
    })
    .sort((left, right) => {
      const leftManaged = getGrantOwnership(left)?.managed === true ? 1 : 0;
      const rightManaged = getGrantOwnership(right)?.managed === true ? 1 : 0;
      return leftManaged - rightManaged || left.id.localeCompare(right.id);
    })[0];
  if (canonical) return canonical;

  const legacy = matching.find((item) => getLegacyGrantOwners(item).includes(owner.ownerId));
  if (legacy) return legacy;

  return matching.find((item) => {
    const ownership = getGrantOwnership(item);
    return (
      ownership?.signature === signature ||
      (!ownership &&
        getLegacyGrantOwners(item).length === 0 &&
        hasMatchingSourceIdentity(item, grant.sourceUuid))
    );
  });
}
