import { MODULE_ID } from "./constants";

export const MUTANTS_HANDBOOK_SETTING = "useMutantsHandbookMutations";

export function registerModuleSettings(): void {
  if (!game) {
    throw new Error("Foundry game global is unavailable during settings registration.");
  }

  game.settings.register(MODULE_ID, MUTANTS_HANDBOOK_SETTING, {
    config: true,
    default: false,
    hint: "FVTT_WFRP_RATTER.Settings.MutantsHandbook.Hint",
    name: "FVTT_WFRP_RATTER.Settings.MutantsHandbook.Name",
    scope: "world",
    type: Boolean,
  });
}

export function useMutantsHandbookMutations(): boolean {
  return game?.settings.get(MODULE_ID, MUTANTS_HANDBOOK_SETTING) === true;
}
