import { MODULE_ID } from "../../../constants";
import { isRecord } from "./documents";
import type { MutationActionActor, MutationActionTest } from "./types";

export interface MutationActionMessage {
  flags?: Record<string, Record<string, unknown> | undefined>;
  id?: string;
  setFlag?: (scope: string, key: string, value: unknown) => Promise<unknown>;
  system?: { test?: MutationActionTest };
}

export function actionIdFromMessage(message: MutationActionMessage): string | undefined {
  const test = message.system?.test;
  const testId =
    test?.options?.["mutationActionId"] ?? test?.preData?.options?.["mutationActionId"];
  if (typeof testId === "string") return testId;
  const action = message.flags?.[MODULE_ID]?.["mutationActionOutcome"];
  return isRecord(action) && typeof action["actionId"] === "string"
    ? action["actionId"]
    : undefined;
}

export function outcomeAlreadyApplied(message: MutationActionMessage): boolean {
  return message.flags?.[MODULE_ID]?.["mutationActionOutcomeApplied"] === true;
}

export async function markOutcomeApplied(message: MutationActionMessage): Promise<void> {
  await message.setFlag?.(MODULE_ID, "mutationActionOutcomeApplied", true);
}

function tokenActor(value: unknown): MutationActionActor | undefined {
  if (!isRecord(value)) return undefined;
  const actor = value["actor"];
  return isRecord(actor) ? (actor as MutationActionActor) : (value as MutationActionActor);
}

export function actionTargets(test?: MutationActionTest): MutationActionActor[] {
  const fromTest = test?.targets?.filter((target) => isRecord(target)) ?? [];
  if (fromTest.length) return fromTest;
  const currentGame = Reflect.get(globalThis, "game") as
    | { user?: { targets?: Iterable<unknown> } }
    | undefined;
  return [...(currentGame?.user?.targets ?? [])].flatMap((target) => tokenActor(target) ?? []);
}

export async function actionActor(
  message: MutationActionMessage,
): Promise<MutationActionActor | undefined> {
  const testActor = message.system?.test
    ? Reflect.get(message.system.test as object, "actor")
    : undefined;
  if (isRecord(testActor)) return testActor as MutationActionActor;
  const action = message.flags?.[MODULE_ID]?.["mutationActionOutcome"];
  const uuid = isRecord(action) ? action["actorUuid"] : undefined;
  if (typeof uuid !== "string") return undefined;
  const resolver = Reflect.get(globalThis, "fromUuid") as
    | ((documentUuid: string) => Promise<unknown>)
    | undefined;
  const actor = await resolver?.(uuid);
  return isRecord(actor) ? (actor as MutationActionActor) : undefined;
}
