import {
  getMutationActionOutcomes,
  type MutationActionDefinition,
} from "../../../../functions/mutants-handbook/actions";
import { activeMutationLevels, testMatchesAction } from "./documents";
import { mutationActionUseCount } from "./usage";
import type { MutationActionActor, MutationActionItem, MutationActionTest } from "./types";

const CARD_MARKER = "data-ratter-mutation-action";

function escapeHtml(value: unknown): string {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function values(value: unknown): string[] {
  if (Array.isArray(value))
    return value.filter((entry): entry is string => typeof entry === "string");
  return typeof value === "string" && value ? [value] : [];
}

function list(label: string, value: unknown): string {
  const entries = values(value);
  if (!entries.length) return "";
  return `<p><strong>${escapeHtml(label)}:</strong> ${entries.map(escapeHtml).join("; ")}</p>`;
}

function resultFacts(
  action: MutationActionDefinition,
  actor: MutationActionActor,
  item: MutationActionItem,
  test: MutationActionTest,
): string {
  const sl = Number(test.result?.SL);
  const wp = actor.system?.characteristics?.["wp"];
  const levels = Math.max(1, activeMutationLevels(actor, action.mutationId));
  const facts = [
    Number.isFinite(sl) ? `SL ${sl}` : undefined,
    Number.isFinite(Number(wp?.value)) ? `WP ${Number(wp?.value)}` : undefined,
    Number.isFinite(Number(wp?.bonus)) ? `WPB ${Number(wp?.bonus)}` : undefined,
    `mutation level ${levels}`,
  ].filter((entry): entry is string => Boolean(entry));
  if (action.usage?.period)
    facts.push(`uses this ${action.usage.period}: ${mutationActionUseCount(action, item)}`);
  return facts.join("; ");
}

function applyMiscast(action: MutationActionDefinition, test: MutationActionTest): void {
  if (!action.miscast || !test.result) return;
  test.result.tables ??= {};
  if (!test.isFumble) {
    const existing = test.result.tables["miscast"];
    if (existing?.["key"] === `${action.miscast}mis`) delete test.result.tables["miscast"];
    return;
  }
  const major = action.miscast === "major";
  const currentGame = Reflect.get(globalThis, "game") as
    | { i18n?: { localize?: (key: string) => string } }
    | undefined;
  test.result.tables["miscast"] = {
    class: "fumble-roll",
    key: major ? "majormis" : "minormis",
    label:
      currentGame?.i18n?.localize?.(major ? "ROLL.MajorMis" : "ROLL.MinorMis") ??
      (major ? "Major Miscast" : "Minor Miscast"),
  };
}

function actionCard(
  action: MutationActionDefinition,
  actor: MutationActionActor,
  item: MutationActionItem,
  test: MutationActionTest,
): string {
  const conditions = values(action.conditions);
  const outcomeAutomation = getMutationActionOutcomes(action.id).length
    ? "<p><strong>Automation:</strong> After accepting the final roll, right-click this chat card and choose Apply Mutant’s Handbook Outcome.</p>"
    : "";
  return [
    `<section ${CARD_MARKER}="${escapeHtml(action.id)}">`,
    `<p><strong>${escapeHtml(action.mutationName)} — ${escapeHtml(action.name)}</strong></p>`,
    list("Target", action.target),
    list("Range", action.range),
    list("Duration", action.duration),
    list("Outcome", action.outcome),
    list("Rules", action.rules),
    conditions.length
      ? `<p><strong>Condition guidance:</strong> ${conditions.map(escapeHtml).join("; ")}. Apply these only after the final roll is accepted.</p>`
      : "",
    `<p><strong>Rolled values:</strong> ${escapeHtml(resultFacts(action, actor, item, test))}</p>`,
    outcomeAutomation,
    "</section>",
  ].join("");
}

export function annotateMutationActionTest(
  action: MutationActionDefinition,
  actor: MutationActionActor,
  item: MutationActionItem,
  test: MutationActionTest,
): void {
  if (!testMatchesAction(item, action.id, test) || !test.result) return;
  applyMiscast(action, test);
  test.result.other ??= [];
  test.result.other = test.result.other.filter((entry) => !entry.includes(CARD_MARKER));
  test.result.other.push(actionCard(action, actor, item, test));
}

export function mutationActionChatCard(action: MutationActionDefinition): string {
  const outcomeAutomation = getMutationActionOutcomes(action.id).length
    ? "<p><strong>Automation:</strong> Right-click this chat card and choose Apply Mutant’s Handbook Outcome.</p>"
    : "";
  return [
    `<section ${CARD_MARKER}="${escapeHtml(action.id)}">`,
    `<h3>${escapeHtml(action.mutationName)} — ${escapeHtml(action.name)}</h3>`,
    list("Target", action.target),
    list("Range", action.range),
    list("Duration", action.duration),
    list("Outcome", action.outcome),
    list("Rules", action.rules),
    list("Condition guidance", action.conditions),
    outcomeAutomation,
    "</section>",
  ].join("");
}
