import type { MutationActionDefinition } from "../../../../functions/mutants-handbook/actions";
import { MODULE_ID } from "../../../constants";
import { actionContext, isRecord } from "./documents";
import type {
  MutationActionActor,
  MutationActionItem,
  MutationActionTest,
  MutationActionUsageState,
  MutationActionUse,
} from "./types";

const USAGE_FLAG = "mutationActionUsage";
const EIGHT_HOURS = 8 * 60 * 60;
const DIMENSIONAL_ACTION_ID = "dimensional-instability-teleport";
const updateQueues = new Map<string, Promise<boolean>>();

interface ActionGame {
  combat?: { id?: string };
  scene?: { id?: string };
  time?: { worldTime?: number };
  user?: { targets?: Iterable<unknown> };
}

function actionGame(): ActionGame | undefined {
  return Reflect.get(globalThis, "game") as ActionGame | undefined;
}

function currentTime(): number {
  const worldTime = Number(actionGame()?.time?.worldTime);
  return Number.isFinite(worldTime) ? worldTime : Math.floor(Date.now() / 1000);
}

function usageState(item: MutationActionItem): MutationActionUsageState {
  const value = item.flags?.[MODULE_ID]?.[USAGE_FLAG];
  if (!isRecord(value) || value["version"] !== 1 || !isRecord(value["actions"])) {
    return { actions: {}, version: 1 };
  }
  const actions: Record<string, MutationActionUse[]> = {};
  for (const [actionId, entries] of Object.entries(value["actions"])) {
    if (!Array.isArray(entries)) continue;
    actions[actionId] = entries.filter(
      (entry): entry is MutationActionUse =>
        isRecord(entry) &&
        typeof entry["id"] === "string" &&
        Number.isFinite(entry["at"]) &&
        typeof entry["period"] === "string" &&
        typeof entry["targetId"] === "string",
    );
  }
  return { actions, version: 1 };
}

function periodKey(period: string | undefined, now: number): string {
  if (period === "day") return `day:${Math.floor(now / 86_400)}`;
  if (period === "scene") {
    return `scene:${actionGame()?.combat?.id ?? actionGame()?.scene?.id ?? "none"}`;
  }
  return period ?? "use";
}

function targetId(value: unknown): string | undefined {
  if (typeof value === "string") return value;
  if (!isRecord(value)) return undefined;
  for (const key of ["token", "id", "uuid", "actor"]) {
    const candidate = value[key];
    if (typeof candidate === "string") return candidate;
    if (isRecord(candidate)) {
      const nested = candidate["uuid"] ?? candidate["id"];
      if (typeof nested === "string") return nested;
    }
  }
  return undefined;
}

function targetIds(action: MutationActionDefinition, test?: MutationActionTest): string[] {
  if (!action.usage?.perTarget) return ["*"];
  const contextTargets = test?.context?.["targets"];
  const values = Array.isArray(contextTargets)
    ? contextTargets
    : [...(actionGame()?.user?.targets ?? [])];
  const ids = [...new Set(values.map(targetId).filter((id): id is string => Boolean(id)))];
  return ids.length ? ids : ["untargeted"];
}

function relevantUses(
  action: MutationActionDefinition,
  item: MutationActionItem,
  now = currentTime(),
): MutationActionUse[] {
  const uses = usageState(item).actions[action.id] ?? [];
  if (action.usage?.period === "eight-hours" || action.id === DIMENSIONAL_ACTION_ID) {
    return uses.filter((entry) => entry.at > now - EIGHT_HOURS);
  }
  const key = periodKey(action.usage?.period, now);
  return uses.filter((entry) => entry.period === key);
}

function maximumUses(action: MutationActionDefinition, actor: MutationActionActor): number {
  const maximum = action.usage?.max;
  if (maximum === "tb") {
    return Math.max(0, Number(actor.system?.characteristics?.["t"]?.bonus) || 0);
  }
  return typeof maximum === "number" ? maximum : Number.POSITIVE_INFINITY;
}

function ensureUseId(test: MutationActionTest): string {
  const context = actionContext(test);
  const existing = context["mutationActionUseId"];
  if (typeof existing === "string" && existing) return existing;
  const generated = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random()}`;
  context["mutationActionUseId"] = generated;
  return generated;
}

function hasCapacity(
  action: MutationActionDefinition,
  actor: MutationActionActor,
  item: MutationActionItem,
  test?: MutationActionTest,
): boolean {
  const maximum = maximumUses(action, actor);
  const uses = relevantUses(action, item);
  const existingId = test?.context?.["mutationActionUseId"];
  return targetIds(action, test).every((target) => {
    const matching = uses.filter((entry) => entry.targetId === target);
    return matching.some((entry) => entry.id === existingId) || matching.length < maximum;
  });
}

export function mutationActionAvailable(
  action: MutationActionDefinition,
  actor: MutationActionActor,
  item: MutationActionItem,
  test?: MutationActionTest,
): boolean {
  const useId = test?.context?.["mutationActionUseId"];
  if (typeof useId === "string" && relevantUses(action, item).some((entry) => entry.id === useId)) {
    return true;
  }
  const advantage = Number(actor.system?.status?.advantage?.value) || 0;
  return advantage >= (action.usage?.advantageCost ?? 0) && hasCapacity(action, actor, item, test);
}

export function mutationActionDifficulty(
  action: MutationActionDefinition,
  item: MutationActionItem,
): string | undefined {
  if (action.mutationName !== "Dimensional Instability") return action.test?.difficulty;
  const difficulties = ["average", "challenging", "difficult", "hard", "vhard"];
  return difficulties[Math.min(difficulties.length - 1, relevantUses(action, item).length)];
}

async function spendAdvantage(actor: MutationActionActor, cost: number): Promise<void> {
  if (cost <= 0) return;
  if (actor.modifyAdvantage) {
    await actor.modifyAdvantage(-cost);
    return;
  }
  const current = Number(actor.system?.status?.advantage?.value) || 0;
  await actor.update?.({ "system.status.advantage.value": Math.max(0, current - cost) });
}

async function recordUse(
  action: MutationActionDefinition,
  actor: MutationActionActor,
  item: MutationActionItem,
  test: MutationActionTest,
): Promise<boolean> {
  const useId = ensureUseId(test);
  if (!mutationActionAvailable(action, actor, item, test)) return false;
  const state = usageState(item);
  const entries = state.actions[action.id] ?? [];
  if (entries.some((entry) => entry.id === useId)) return true;

  await spendAdvantage(actor, action.usage?.advantageCost ?? 0);
  const now = currentTime();
  const period = periodKey(action.usage?.period, now);
  const additions = targetIds(action, test).map((target) => ({
    at: now,
    id: useId,
    period,
    targetId: target,
  }));
  const retained = entries.filter((entry) => entry.at > now - 32 * 86_400).slice(-99);
  state.actions[action.id] = [...retained, ...additions];
  await item.update?.({ [`flags.${MODULE_ID}.${USAGE_FLAG}`]: state });
  return true;
}

export async function recordActionUse(
  action: MutationActionDefinition,
  actor: MutationActionActor,
  item: MutationActionItem,
  test: MutationActionTest,
): Promise<boolean> {
  const key = `${item.uuid ?? item.id ?? "item"}:${action.id}`;
  const previous = updateQueues.get(key) ?? Promise.resolve(true);
  const current = previous.catch(() => false).then(() => recordUse(action, actor, item, test));
  updateQueues.set(key, current);
  try {
    return await current;
  } finally {
    if (updateQueues.get(key) === current) updateQueues.delete(key);
  }
}

export function mutationActionUseCount(
  action: MutationActionDefinition,
  item: MutationActionItem,
): number {
  return relevantUses(action, item).length;
}
