import type { WfrpActor, WfrpMutationItem } from "../../../../types/foundry";
import type { MutationGrantDefinition } from "../../../../types/mutants-handbook";
import { MODULE_ID } from "../../../constants";
import {
  configureGrantData,
  getGrantOwnership,
  grantDataMatches,
  mutationGrantSignature,
  mutationRankGrantIdentity,
  mutationRankGrantIdentityFromSignature,
  type MutationSkillGrantLedger,
  type MutationSkillGrantOwner,
} from "./grant-data";
import {
  actorItems,
  clearLedgerChanges,
  isAutomationManaged,
  isItem,
  setAdvances,
  setLedgerFlag,
  updateItem,
} from "./ranked-skill-items";
import {
  hasRankedIdentity,
  rankedBaseAdvances,
  rankedGrantData,
  rankedPriority,
} from "./grant-reconciliation/ranked-grant-data";

export interface RankedSkillGrantRequest {
  grant: MutationGrantDefinition;
  mutation: WfrpMutationItem;
}

interface RankedSkillContribution extends MutationSkillGrantOwner {
  grant: MutationGrantDefinition;
  identity: string;
  mutationName: string;
  name: string;
}

function compare(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function compatible(item: WfrpMutationItem, contribution: RankedSkillContribution): boolean {
  const grant = { ...contribution.grant };
  delete grant.ranks;
  return grantDataMatches(item, { name: contribution.name } as WfrpMutationItem, grant);
}

async function desiredContributions(
  actor: WfrpActor,
  requests: RankedSkillGrantRequest[],
): Promise<RankedSkillContribution[]> {
  const sourceNames = new Map<string, string>();
  await Promise.all(
    requests.map(async ({ grant, mutation }) => {
      if (grant.type !== "skill" && grant.type !== "talent") return;
      const identity = mutationRankGrantIdentity(grant);
      if (grant.configure?.name || sourceNames.has(identity)) return;
      const signature = mutationGrantSignature(grant);
      const owned = actorItems(actor).find(
        (item) =>
          item.type === grant.type &&
          rankedGrantData(item)?.owners.some(
            (owner) =>
              owner.sourceUuid === grant.sourceUuid &&
              ((owner.ownerId === mutation.id && owner.grantKey === grant.key) ||
                owner.signature === signature),
          ),
      );
      if (owned) {
        sourceNames.set(identity, owned.name);
        return;
      }
      const source = await fromUuid(grant.sourceUuid);
      if (isItem(source) && source.type === grant.type) sourceNames.set(identity, source.name);
    }),
  );

  return requests.flatMap(({ grant, mutation }) => {
    if (grant.type !== "skill" && grant.type !== "talent") return [];
    const identity = mutationRankGrantIdentity(grant);
    return [
      {
        grant,
        grantKey: grant.key,
        identity,
        mutationName: mutation.name,
        name: grant.configure?.name ?? sourceNames.get(identity) ?? grant.name,
        ownerId: mutation.id,
        ranks: grant.ranks ?? 1,
        signature: mutationGrantSignature(grant),
        sourceUuid: grant.sourceUuid,
      },
    ];
  });
}

function contributionOwners(contributions: RankedSkillContribution[]): MutationSkillGrantOwner[] {
  return contributions.map(({ grantKey, ownerId, ranks, signature, sourceUuid }) => ({
    grantKey,
    ownerId,
    ranks,
    signature,
    sourceUuid,
  }));
}

async function createRankedSkill(
  actor: WfrpActor,
  contributions: RankedSkillContribution[],
): Promise<void> {
  const first = contributions[0];
  if (!first) return;
  const source = await fromUuid(first.sourceUuid);
  if (!isItem(source) || source.type !== first.grant.type) {
    ui.notifications.warn(
      `${first.mutationName}: could not grant ${first.name}. Enable its source module and reconcile mutation automation.`,
    );
    return;
  }

  const data = configureGrantData(source.toObject(), first.grant);
  delete data["_id"];
  delete data["_key"];
  // A positive-advance Skill or Talent is merged before Foundry creates it, losing this module's
  // ledger flags. Create a zero-advance shell and apply the contribution in a normal update.
  setAdvances(data, 0);
  setLedgerFlag(data, {
    appliedRanks: 0,
    managed: true,
    owners: [],
    version: 1,
  });
  const created = await actor.createEmbeddedDocuments("Item", [data], {
    skipExperienceChecks: true,
    skipSpecialisationChoice: true,
  });
  const createdItem = created.find(isItem);
  if (!createdItem && !actorItems(actor).some((item) => compatible(item, first))) {
    throw new Error(`${first.mutationName}: Foundry prevented the ${first.name} grant.`);
  }

  // Re-read the actor collection: another client may have created the same Skill while the
  // shell was being added. Group reconciliation deterministically adopts one and converges any
  // zero-base automation duplicates without ever relying on WFRP's merge result.
  await reconcileRankedSkillGroup(actor, first.identity, contributions, false);
}

async function clearRankedSkillGroup(
  actor: WfrpActor,
  candidates: WfrpMutationItem[],
): Promise<void> {
  const deleteIds: string[] = [];
  for (const item of candidates) {
    const ranked = rankedGrantData(item);
    if (!ranked) continue;
    const base = rankedBaseAdvances(item);
    if (ranked.managed && base === 0 && !getGrantOwnership(item)) deleteIds.push(item.id);
    else await updateItem(actor, item, clearLedgerChanges(base));
  }
  if (deleteIds.length > 0) await actor.deleteEmbeddedDocuments("Item", deleteIds);
}

async function reconcileRankedSkillGroup(
  actor: WfrpActor,
  identity: string,
  contributions: RankedSkillContribution[],
  allowCreate = true,
): Promise<void> {
  const first = contributions[0];
  const candidates = actorItems(actor)
    .filter((item) => (first ? compatible(item, first) : hasRankedIdentity(item, identity)))
    .sort(
      (left, right) => rankedPriority(left) - rankedPriority(right) || compare(left.id, right.id),
    );

  if (contributions.length === 0) {
    await clearRankedSkillGroup(actor, candidates);
    return;
  }
  const canonical = candidates[0];
  if (!canonical) {
    if (!allowCreate) {
      throw new Error(
        `${first?.name ?? "Ranked Item"}: Foundry did not retain the mutation grant.`,
      );
    }
    await createRankedSkill(actor, contributions);
    return;
  }

  const automatedExtras = candidates.slice(1).filter((item) => rankedGrantData(item));
  const userDuplicates = candidates.slice(1).filter((item) => !rankedGrantData(item));
  if (userDuplicates.length > 0) {
    ui.notifications.warn(
      `${first?.name}: multiple user-owned Items share this configuration. Mutation advances were applied only to ${canonical.name}; review the duplicates manually.`,
    );
  }

  const total = contributions.reduce((sum, contribution) => sum + contribution.ranks, 0);
  const base = rankedBaseAdvances(canonical, total);
  const current = rankedGrantData(canonical);
  const ledger: MutationSkillGrantLedger = {
    appliedRanks: total,
    managed: current?.managed ?? getGrantOwnership(canonical)?.managed ?? false,
    owners: contributionOwners(contributions),
    version: 1,
  };
  await updateItem(actor, canonical, {
    "system.advances.value": base + total,
    [`flags.${MODULE_ID}.mutationSkillGrant`]: ledger,
  });

  const deleteIds: string[] = [];
  for (const extra of automatedExtras) {
    const extraBase = rankedBaseAdvances(extra);
    if (
      (isAutomationManaged(extra) || rankedGrantData(extra)?.managed) &&
      extraBase === 0 &&
      !getGrantOwnership(extra)
    ) {
      deleteIds.push(extra.id);
    } else {
      await updateItem(actor, extra, clearLedgerChanges(extraBase));
      if (extraBase > 0) {
        ui.notifications.warn(
          `${first?.name}: retained a duplicate Item containing non-mutation advances; review the duplicate manually.`,
        );
      }
    }
  }
  if (deleteIds.length > 0) await actor.deleteEmbeddedDocuments("Item", deleteIds);
}

export async function reconcileRankedSkillGrants(
  actor: WfrpActor,
  requests: RankedSkillGrantRequest[],
): Promise<void> {
  const desired = await desiredContributions(actor, requests);
  const groups = new Map<string, RankedSkillContribution[]>();
  for (const contribution of desired) {
    const group = groups.get(contribution.identity) ?? [];
    group.push(contribution);
    groups.set(contribution.identity, group);
  }
  const existing = new Set<string>();
  for (const item of actorItems(actor)) {
    for (const owner of rankedGrantData(item)?.owners ?? []) {
      const identity = mutationRankGrantIdentityFromSignature(owner.signature);
      if (identity) existing.add(identity);
    }
  }

  for (const identity of [...existing].filter((entry) => !groups.has(entry)).sort(compare)) {
    await reconcileRankedSkillGroup(actor, identity, []);
  }
  for (const identity of [...groups.keys()].sort(compare)) {
    const contributions = (groups.get(identity) ?? []).sort(
      (left, right) =>
        compare(left.ownerId, right.ownerId) || compare(left.grantKey, right.grantKey),
    );
    await reconcileRankedSkillGroup(actor, identity, contributions);
  }
}
