import type { WfrpActor, WfrpMutationItem } from "../../../types/foundry";
import type { MutationNature } from "../../../types/mutants-handbook";
import { MODULE_ID } from "../../constants";
import { PENDING_CORRUPTION_FLAG, PENDING_MUTATION_FLAG } from "./constants";
import type { ResolvedMutation } from "./document-types";
import { updateActor } from "./updates";

interface PendingCorruptionTest {
  kind: "test";
  messageId: string;
  version: 1;
}

export interface PendingMutationDrop {
  actorUuid: string;
  kind: "mutation";
  mutationName: string;
  nature: MutationNature;
  token: string;
  version: 1;
}

export type PendingCorruption = PendingCorruptionTest | PendingMutationDrop;

const pendingCorruptionPath = `flags.${MODULE_ID}.${PENDING_CORRUPTION_FLAG}`;
export const removePendingCorruptionPath = `flags.${MODULE_ID}.-=${PENDING_CORRUPTION_FLAG}`;
export const pendingMutationPath = `flags.${MODULE_ID}.${PENDING_MUTATION_FLAG}`;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isMutationNature(value: unknown): value is MutationNature {
  return value === "mental" || value === "physical";
}

function readPendingCorruption(value: unknown): PendingCorruption | undefined {
  if (!isRecord(value) || value["version"] !== 1) return undefined;
  if (value["kind"] === "test" && typeof value["messageId"] === "string") {
    return value as unknown as PendingCorruptionTest;
  }
  if (
    value["kind"] === "mutation" &&
    typeof value["actorUuid"] === "string" &&
    typeof value["mutationName"] === "string" &&
    isMutationNature(value["nature"]) &&
    typeof value["token"] === "string"
  ) {
    return value as unknown as PendingMutationDrop;
  }
  return undefined;
}

export function getPendingCorruption(actor: WfrpActor): PendingCorruption | undefined {
  return readPendingCorruption(actor.getFlag(MODULE_ID, PENDING_CORRUPTION_FLAG));
}

export function hasPendingCorruption(actor: WfrpActor): boolean {
  return getPendingCorruption(actor) !== undefined;
}

export async function markPendingCorruptionTest(
  actor: WfrpActor,
  messageId: string,
): Promise<void> {
  await updateActor(actor, {
    [pendingCorruptionPath]: {
      kind: "test",
      messageId,
      version: 1,
    } satisfies PendingCorruptionTest,
  });
}

export async function clearPendingCorruption(actor: WfrpActor): Promise<void> {
  await updateActor(actor, { [removePendingCorruptionPath]: null });
}

export function readPendingMutation(item: WfrpMutationItem): PendingMutationDrop | undefined {
  const direct = item.flags?.[MODULE_ID]?.[PENDING_MUTATION_FLAG];
  const value = direct ?? item.getFlag(MODULE_ID, PENDING_MUTATION_FLAG);
  const pending = readPendingCorruption(value);
  return pending?.kind === "mutation" ? pending : undefined;
}

function ensureRecord(parent: Record<string, unknown>, key: string): Record<string, unknown> {
  const existing = parent[key];
  if (isRecord(existing)) return existing;
  const record: Record<string, unknown> = {};
  parent[key] = record;
  return record;
}

function hasAcquisitionScript(data: Record<string, unknown>): boolean {
  const effects = data["effects"];
  if (!Array.isArray(effects)) return false;
  return effects.some((effect) => {
    if (!isRecord(effect)) return false;
    const system = effect["system"];
    const scriptData = isRecord(system) ? system["scriptData"] : undefined;
    return (
      Array.isArray(scriptData) &&
      scriptData.some(
        (script) =>
          isRecord(script) &&
          script["trigger"] === "immediate" &&
          typeof script["label"] === "string" &&
          script["label"].startsWith("Acquire ") &&
          typeof script["script"] === "string" &&
          !script["script"].includes("prepareMutationAcquisition"),
      )
    );
  });
}

function mutationCardGateEffect(
  data: Record<string, unknown>,
  mutation: ResolvedMutation,
): Record<string, unknown> {
  const id = crypto.randomUUID().replaceAll("-", "").slice(0, 16);
  const img = typeof data["img"] === "string" ? data["img"] : "icons/svg/aura.svg";
  const bonus = mutation.nature === "physical" ? "t" : "wp";
  const name = JSON.stringify(mutation.name);
  const nature = JSON.stringify(mutation.nature);
  return {
    _id: id,
    changes: [],
    description: "",
    disabled: false,
    duration: {},
    flags: { [MODULE_ID]: { scope: "corruption-card" }, wfrp4e: {} },
    img,
    name: `${mutation.name} — Corruption Acquisition`,
    origin: null,
    statuses: [],
    tint: "#ffffff",
    transfer: true,
    type: "base",
    system: {
      sourceData: {},
      transferData: {
        area: { aura: {} },
        avoidTest: { value: "none" },
        documentType: "Actor",
        equipTransfer: false,
        prompt: false,
        type: "document",
      },
      scriptData: [
        {
          async: true,
          label: `Resolve ${mutation.name} Corruption Card`,
          options: {
            deleteEffect: true,
            dialog: {
              activateScript: "",
              hideScript: "",
              submissionScript: "",
              targeter: false,
            },
            immediate: { deleteEffect: true },
          },
          trigger: "immediate",
          script: `const options = args.options ?? {};
const actor = this.actor;
const moduleId = "${MODULE_ID}";
const pending = this.item.flags[moduleId].${PENDING_MUTATION_FLAG};
const expected = actor.getFlag(moduleId, "${PENDING_CORRUPTION_FLAG}");
const mutationName = ${name};
if (pending.actorUuid !== actor.uuid || pending.mutationName !== mutationName || pending.nature !== ${nature} || expected?.kind !== "mutation" || expected.token !== pending.token) {
  ui.notifications.warn(mutationName + " is no longer the pending mutation for " + actor.name + ".");
  options.abortItemCreation = true;
  options.mutationAcquisitionCancelled = true;
  return false;
}
const resilience = Number(actor.system.status.resilience.value ?? 0);
if (resilience > 0 && await foundry.applications.api.DialogV2.confirm({
  window: {title: "Resist " + mutationName},
  content: "<p>Spend 1 Resilience to resist " + mutationName + "?</p>",
  yes: {label: "Spend Resilience"},
  no: {label: "Keep Mutation"},
  rejectClose: false
})) {
  const loss = Math.max(0, Number(actor.system.characteristics.${bonus}.bonus ?? 0));
  await actor.update({
    ["flags." + moduleId + ".-=${PENDING_CORRUPTION_FLAG}"]: null,
    "system.status.corruption.value": Math.max(0, Number(actor.system.status.corruption.value) - loss),
    "system.status.resilience.value": resilience - 1
  });
  options.abortItemCreation = true;
  options.mutationAcquisitionCancelled = true;
  await ChatMessage.create({content: "<p><strong>" + actor.name + "</strong> spends Resilience and resists <strong>" + mutationName + "</strong>.</p>"});
  return false;
}
options.mutationAcquisitionCanReroll = false;
options.mutationAcquisitionHandlesChimeranRetirement = true;
return true;`,
        },
      ],
      zone: {},
    },
  };
}

function preparePostedData(
  mutation: ResolvedMutation,
  pending: PendingMutationDrop,
): Record<string, unknown> {
  const data = structuredClone(mutation.data);
  const flags = ensureRecord(data, "flags");
  const moduleFlags = ensureRecord(flags, MODULE_ID);
  moduleFlags[PENDING_MUTATION_FLAG] = pending;
  if (!hasAcquisitionScript(data)) {
    throw new Error(
      `${mutation.name} has no embedded Mutant's Handbook acquisition script and cannot be posted.`,
    );
  }
  if (Array.isArray(data["effects"])) {
    data["effects"] = [mutationCardGateEffect(data, mutation), ...data["effects"]];
  }
  return data;
}

export async function postPendingMutation(
  actor: WfrpActor,
  mutation: ResolvedMutation,
): Promise<void> {
  const previous = getPendingCorruption(actor);
  const pending: PendingMutationDrop = {
    actorUuid: actor.uuid,
    kind: "mutation",
    mutationName: mutation.name,
    nature: mutation.nature,
    token: crypto.randomUUID(),
    version: 1,
  };
  const document = new Item.implementation(preparePostedData(mutation, pending));

  await updateActor(actor, { [pendingCorruptionPath]: pending });
  try {
    await document.postItem(
      undefined,
      previous?.kind === "test"
        ? { "flags.wfrp4e.sourceMessageId": previous.messageId }
        : undefined,
    );
  } catch (error) {
    await updateActor(actor, {
      ...(previous
        ? { [pendingCorruptionPath]: previous }
        : { [removePendingCorruptionPath]: null }),
    });
    throw error;
  }
}
