import {
  getMutationAction,
  getMutationActionOutcomes,
  type MutationActionOutcome,
  type MutationOutcomeSubject,
} from "../../../../functions/mutants-handbook/actions";
import {
  actionActor,
  actionIdFromMessage,
  actionTargets,
  markOutcomeApplied,
  outcomeAlreadyApplied,
} from "./outcome-documents";
import type { MutationActionMessage } from "./outcome-documents";
import { applyTimedMutationEffect } from "./timed-effects";
import { applyMutationForm } from "./forms";
import { createMutationCompanion } from "./companions";
import type { MutationActionActor, MutationActionTest } from "./types";

const applyingOutcomes = new WeakSet<object>();

function testSucceeded(test?: MutationActionTest): boolean {
  if (!test) return true;
  if (typeof test.failed === "boolean") return !test.failed;
  return test.result?.outcome !== "failure";
}

function applies(outcome: MutationActionOutcome, test?: MutationActionTest): boolean {
  if (outcome.when === "always") return true;
  return outcome.when === "success" ? testSucceeded(test) : !testSucceeded(test);
}

function subjects(
  subject: MutationOutcomeSubject,
  actor: MutationActionActor,
  targets: MutationActionActor[],
): MutationActionActor[] {
  return subject === "self" ? [actor] : targets;
}

async function rollOutcome(formula: string, label: string): Promise<void> {
  const RollClass = Reflect.get(globalThis, "Roll") as
    | (new (formula: string) => {
        evaluate: () => Promise<{
          toMessage?: (data: Record<string, unknown>) => Promise<unknown>;
        }>;
      })
    | undefined;
  if (!RollClass) return;
  const rolled = await new RollClass(formula).evaluate();
  await rolled.toMessage?.({ flavor: label });
}

async function applyFollowUp(
  outcome: Extract<MutationActionOutcome, { kind: "follow-up-test" }>,
  targets: MutationActionActor[],
  actionName: string,
): Promise<void> {
  for (const target of targets) {
    const context = {
      appendTitle: ` — ${actionName} follow-up`,
      fields: { difficulty: outcome.difficulty },
    };
    const test = outcome.skill
      ? await target.setupSkill?.(outcome.skill, context)
      : await target.setupCharacteristic?.(outcome.characteristic ?? "wp", context);
    if (!test?.roll) continue;
    await test.roll();
    if (!testSucceeded(test)) {
      for (const condition of outcome.failureConditions) {
        const amount =
          condition.condition === "broken" && target.has?.("Skittish")
            ? 3
            : (condition.amount ?? 1);
        await target.addCondition?.(condition.condition, amount);
      }
      if (outcome.failureRoll) {
        await rollOutcome(outcome.failureRoll.formula, outcome.failureRoll.label);
      }
    }
  }
}

function amount(
  kind: "fellowship-plus-sl" | "sl" | number,
  actor: MutationActionActor,
  test?: MutationActionTest,
): number {
  const sl = Number(test?.result?.SL) || 0;
  if (kind === "sl") return Math.max(0, sl);
  if (kind === "fellowship-plus-sl") {
    return Math.max(0, (Number(actor.system?.characteristics?.["fel"]?.value) || 0) + sl);
  }
  return kind;
}

async function applyOne(
  outcome: MutationActionOutcome,
  actor: MutationActionActor,
  targets: MutationActionActor[],
  test: MutationActionTest | undefined,
  action: NonNullable<ReturnType<typeof getMutationAction>>,
): Promise<void> {
  if (outcome.kind === "roll") return rollOutcome(outcome.formula, outcome.label);
  if (outcome.kind === "follow-up-test") return applyFollowUp(outcome, targets, action.name);
  if (outcome.kind === "companion") {
    return createMutationCompanion(outcome.companion, actor, action);
  }
  if (outcome.kind === "form") {
    return applyMutationForm(outcome.form, outcome.mode, actor, action, test, targets[0]);
  }
  const affected = subjects(outcome.subject, actor, targets);
  if (outcome.kind === "condition") {
    for (const subject of affected) {
      const conditionAmount = amount(outcome.amount ?? 1, actor, test);
      await subject.addCondition?.(outcome.condition, conditionAmount);
    }
    return;
  }
  if (outcome.kind === "remove-condition") {
    const count = amount(outcome.amount ?? 1, actor, test);
    for (const subject of affected) {
      for (let index = 0; index < count; index += 1)
        await subject.removeCondition?.(outcome.condition);
    }
    return;
  }
  if (outcome.kind === "heal") {
    const healing = amount(outcome.amount, actor, test);
    for (const subject of affected) await subject.modifyWounds?.(healing);
    return;
  }
  if (outcome.kind === "effect") {
    for (const subject of affected) {
      await applyTimedMutationEffect(outcome.effect, subject, action, test, actor);
    }
  }
}

function warn(message: string): void {
  const currentUi = Reflect.get(globalThis, "ui") as
    | { notifications?: { warn?: (text: string) => void } }
    | undefined;
  currentUi?.notifications?.warn?.(message);
}

export function messageHasMutationActionOutcome(message: MutationActionMessage): boolean {
  const actionId = actionIdFromMessage(message);
  return Boolean(actionId && getMutationActionOutcomes(actionId).length);
}

export async function applyMutationActionOutcome(messageValue: unknown): Promise<boolean> {
  if (typeof messageValue !== "object" || messageValue === null) return false;
  const message = messageValue as MutationActionMessage;
  if (applyingOutcomes.has(message) || outcomeAlreadyApplied(message)) return false;
  const actionId = actionIdFromMessage(message);
  const action = actionId ? getMutationAction(actionId) : undefined;
  if (!action) return false;
  const test = message.system?.test;
  const actor = await actionActor(message);
  if (!actor) return false;
  const outcomes = getMutationActionOutcomes(action.id).filter((outcome) => applies(outcome, test));
  const targets = actionTargets(test);
  if (
    outcomes.some(
      (outcome) =>
        (outcome.kind !== "roll" && outcome.subject === "targets") ||
        (outcome.kind === "form" && outcome.source === "targets"),
    ) &&
    targets.length === 0
  ) {
    warn(`Target one or more Actors before applying ${action.name}.`);
    return false;
  }
  applyingOutcomes.add(message);
  try {
    for (const outcome of outcomes) await applyOne(outcome, actor, targets, test, action);
    await markOutcomeApplied(message);
    return true;
  } finally {
    applyingOutcomes.delete(message);
  }
}
