import { MODULE_ID } from "../../constants";
import { applyMutationActionOutcome, messageHasMutationActionOutcome } from "./actions/outcomes";

function messageFor(target: HTMLElement) {
  const messageId = target.dataset["messageId"];
  return messageId ? game?.messages.get(messageId) : undefined;
}

export function registerHandbookTestContextOptions(): void {
  Hooks.on("getChatMessageContextOptions", (_html, options) => {
    if (!game) {
      return;
    }

    options.push({
      callback: async (target) => {
        const message = messageFor(target);
        if (message) await applyMutationActionOutcome(message);
      },
      condition: (target) => {
        const message = messageFor(target);
        return Boolean(
          message &&
          message.flags?.[MODULE_ID]?.["mutationActionOutcomeApplied"] !== true &&
          messageHasMutationActionOutcome(message),
        );
      },
      name: "Apply Mutant’s Handbook Outcome",
    });
  });
}
