import type { WfrpMutationItem } from "../../../../../types/foundry";
import type { MutationGrantDefinition } from "../../../../../types/mutants-handbook";
import { MUTATION_ACTION_SUPPORT_ITEM_IDS } from "../../../../../functions/mutants-handbook/actions";
import { MODULE_ID } from "../../../../constants";

const GRANT_TYPES = new Set(["armour", "psychology", "skill", "talent", "trait", "weapon"]);
const GRANT_STACKS = new Set(["configuration", "rank", "singleton"]);
const AGGREGATE_KEY_MAX_LENGTH = 256;
const UNSAFE_PATH_PARTS = new Set(["__proto__", "constructor", "prototype"]);
const SOURCE_UUID_PATTERN = /^Compendium\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.Item\.[A-Za-z0-9_-]+$/;
const GRANT_KEY_PATTERN = /^[A-Za-z0-9][A-Za-z0-9:_-]{0,127}$/;
const INVALID = Symbol("invalid-acquisition-value");
const TAIL_ID = "bSVbWpX8AcBSIyTU";
const TAIL_ACTIONS = {
  mace: ["tail-mace-free-attack", "Mace Tail: Free Attack"],
  prehensile: ["tail-prehensile-free-attack", "Prehensile Tail: Free Attack"],
  scorpion: ["tail-scorpion-free-attack", "Scorpion Stinger: Free Attack"],
} as const;

function isRecord(value: unknown): value is Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function sanitizeStoredValue(
  value: unknown,
  seen: Set<object>,
  depth = 0,
): unknown | typeof INVALID {
  if (value === null || typeof value === "string" || typeof value === "boolean") {
    return value;
  }
  if (typeof value === "number") return Number.isFinite(value) ? value : INVALID;
  if (depth >= 20 || typeof value !== "object" || value === null || seen.has(value)) {
    return INVALID;
  }

  seen.add(value);
  if (Array.isArray(value)) {
    const result: unknown[] = [];
    for (const entry of value) {
      const sanitized = sanitizeStoredValue(entry, seen, depth + 1);
      if (sanitized === INVALID) return INVALID;
      result.push(sanitized);
    }
    seen.delete(value);
    return result;
  }
  if (!isRecord(value)) return INVALID;

  const result: Record<string, unknown> = {};
  for (const [key, entry] of Object.entries(value)) {
    if (UNSAFE_PATH_PARTS.has(key)) return INVALID;
    const sanitized = sanitizeStoredValue(entry, seen, depth + 1);
    if (sanitized === INVALID) return INVALID;
    result[key] = sanitized;
  }
  seen.delete(value);
  return result;
}

function configurationPath(path: string): string | undefined {
  const normalized = path.replace(/^system\./, "");
  const parts = normalized.split(".");
  return normalized.length > 0 && parts.every((part) => part && !UNSAFE_PATH_PARTS.has(part))
    ? normalized
    : undefined;
}

function sanitizeConfiguration(value: unknown): MutationGrantDefinition["configure"] | undefined {
  if (value === undefined) return undefined;
  if (!isRecord(value)) return undefined;
  if (Object.keys(value).some((key) => key !== "name" && key !== "system")) return undefined;

  const configure: NonNullable<MutationGrantDefinition["configure"]> = {};
  if (value["name"] !== undefined) {
    if (typeof value["name"] !== "string" || value["name"].trim().length === 0) return undefined;
    configure.name = value["name"];
  }
  if (value["system"] !== undefined) {
    if (!isRecord(value["system"])) return undefined;
    const system: Record<string, unknown> = {};
    const paths: string[] = [];
    for (const [rawPath, entry] of Object.entries(value["system"])) {
      const path = configurationPath(rawPath);
      const sanitized = sanitizeStoredValue(entry, new Set());
      if (!path || sanitized === INVALID) return undefined;
      if (paths.some((other) => path.startsWith(`${other}.`) || other.startsWith(`${path}.`))) {
        return undefined;
      }
      paths.push(path);
      system[rawPath] = sanitized;
    }
    configure.system = system;
  }
  return configure;
}

export function sanitizeMutationGrant(value: unknown): MutationGrantDefinition | undefined {
  if (!isRecord(value)) return undefined;
  const allowed = new Set([
    "aggregate",
    "aggregateKey",
    "configure",
    "key",
    "name",
    "ranks",
    "scope",
    "sourceUuid",
    "stack",
    "type",
  ]);
  if (Object.keys(value).some((key) => !allowed.has(key))) return undefined;

  const { key, name, sourceUuid, type } = value;
  if (typeof key !== "string" || !GRANT_KEY_PATTERN.test(key)) return undefined;
  if (typeof name !== "string" || name.trim().length === 0) return undefined;
  if (typeof sourceUuid !== "string" || !SOURCE_UUID_PATTERN.test(sourceUuid)) return undefined;
  if (typeof type !== "string" || !GRANT_TYPES.has(type)) return undefined;

  const stack = value["stack"] ?? "singleton";
  if (typeof stack !== "string" || !GRANT_STACKS.has(stack)) return undefined;
  if (stack === "rank" && type !== "skill" && type !== "talent") return undefined;
  if (value["scope"] !== undefined && value["scope"] !== "first") return undefined;
  if (value["aggregate"] !== undefined && value["aggregate"] !== "latest") return undefined;
  if (value["aggregate"] === "latest" && stack !== "configuration") return undefined;
  const aggregateKey = value["aggregateKey"];
  if (
    aggregateKey !== undefined &&
    (typeof aggregateKey !== "string" ||
      aggregateKey.trim().length === 0 ||
      aggregateKey.length > AGGREGATE_KEY_MAX_LENGTH)
  ) {
    return undefined;
  }
  if (
    value["ranks"] !== undefined &&
    (!Number.isSafeInteger(value["ranks"]) || Number(value["ranks"]) < 1)
  ) {
    return undefined;
  }
  if (value["ranks"] !== undefined && type !== "skill" && type !== "talent") return undefined;

  const configure = sanitizeConfiguration(value["configure"]);
  if (value["configure"] !== undefined && configure === undefined) return undefined;
  return {
    ...(value["aggregate"] === "latest" ? { aggregate: "latest" as const } : {}),
    ...(typeof aggregateKey === "string" ? { aggregateKey } : {}),
    ...(configure ? { configure } : {}),
    key,
    name,
    ...(value["ranks"] === undefined ? {} : { ranks: Number(value["ranks"]) }),
    ...(value["scope"] === "first" ? { scope: "first" as const } : {}),
    sourceUuid,
    stack: stack as NonNullable<MutationGrantDefinition["stack"]>,
    type: type as MutationGrantDefinition["type"],
  };
}

function validResolvedAcquisition(value: unknown): value is Record<string, unknown> {
  if (!isRecord(value) || value["status"] !== "resolved") return false;
  if (value["version"] !== undefined && value["version"] !== 1) return false;
  if (!Number.isSafeInteger(value["occurrence"]) || Number(value["occurrence"]) < 1) return false;
  if (!isRecord(value["rolls"]) || !isRecord(value["selections"])) return false;
  if (sanitizeStoredValue(value["rolls"], new Set()) === INVALID) return false;
  if (sanitizeStoredValue(value["selections"], new Set()) === INVALID) return false;
  if (!Array.isArray(value["grants"])) return false;
  if (value["acceptedBlocks"] === undefined) return true;
  return (
    Array.isArray(value["acceptedBlocks"]) &&
    value["acceptedBlocks"].every(
      (entry) =>
        isRecord(entry) &&
        Object.keys(entry).every((key) => key === "kind" || key === "message") &&
        typeof entry["kind"] === "string" &&
        typeof entry["message"] === "string",
    )
  );
}

export function resolvedAcquisitionGrants(item: WfrpMutationItem): MutationGrantDefinition[] {
  const automation = item.flags?.[MODULE_ID]?.["mutationAutomation"];
  if (!isRecord(automation)) return [];
  // Werebeast acquisition describes a dormant form. Phase 5 materializes these
  // grants only while the managed Werebeast form is active.
  if (automation["definitionId"] === "mNNavbJayRcsyeXJ") return [];
  const state = automation["state"];
  if (!isRecord(state) || !validResolvedAcquisition(state["acquisition"])) return [];

  const grants = (state["acquisition"]["grants"] as unknown[])
    .map(sanitizeMutationGrant)
    .filter((grant): grant is MutationGrantDefinition => grant !== undefined);
  const counts = new Map<string, number>();
  for (const grant of grants) counts.set(grant.key, (counts.get(grant.key) ?? 0) + 1);
  return grants.filter((grant) => counts.get(grant.key) === 1);
}

export function acquisitionOccurrence(item: WfrpMutationItem): number | undefined {
  const automation = item.flags?.[MODULE_ID]?.["mutationAutomation"];
  if (!isRecord(automation)) return undefined;
  const state = automation["state"];
  if (!isRecord(state)) return undefined;
  const acquisition = state["acquisition"];
  if (!isRecord(acquisition)) return undefined;
  if (acquisition["version"] !== undefined && acquisition["version"] !== 1) return undefined;
  const occurrence = acquisition["occurrence"];
  return Number.isSafeInteger(occurrence) && Number(occurrence) > 0
    ? Number(occurrence)
    : undefined;
}

function migratedTailActionGrant(item: WfrpMutationItem): MutationGrantDefinition | undefined {
  const automation = item.flags?.[MODULE_ID]?.["mutationAutomation"];
  if (!isRecord(automation) || automation["definitionId"] !== TAIL_ID) return undefined;
  const state = automation["state"];
  if (!isRecord(state)) return undefined;
  const acquisition = state["acquisition"];
  if (!isRecord(acquisition) || acquisition["status"] !== "resolved") return undefined;
  const selections = acquisition["selections"];
  if (!isRecord(selections) || typeof selections["tail"] !== "string") return undefined;
  const action = TAIL_ACTIONS[selections["tail"] as keyof typeof TAIL_ACTIONS];
  if (!action) return undefined;
  const [actionId, name] = action;
  return {
    key: `mutation-action:${actionId}`,
    name,
    sourceUuid: `Compendium.${MODULE_ID}.ratter-11-items.Item.${MUTATION_ACTION_SUPPORT_ITEM_IDS[actionId]}`,
    stack: "singleton",
    type: "trait",
  };
}

export function effectiveMutationGrants(
  item: WfrpMutationItem,
  staticGrants: readonly MutationGrantDefinition[] = [],
): MutationGrantDefinition[] {
  const sanitizedStatic = staticGrants
    .map(sanitizeMutationGrant)
    .filter((grant): grant is MutationGrantDefinition => grant !== undefined);
  const effective = new Map(sanitizedStatic.map((grant) => [grant.key, grant]));
  const migratedTailGrant = migratedTailActionGrant(item);
  if (migratedTailGrant) effective.set(migratedTailGrant.key, migratedTailGrant);
  for (const grant of resolvedAcquisitionGrants(item)) {
    const base = effective.get(grant.key);
    const sameConfigurationStack =
      base?.stack === "configuration" && grant.stack === "configuration";
    effective.set(grant.key, {
      ...grant,
      ...(sameConfigurationStack && base.aggregate === "latest" && grant.aggregate === undefined
        ? { aggregate: "latest" as const }
        : {}),
      ...(sameConfigurationStack && base.aggregateKey && grant.aggregateKey === undefined
        ? { aggregateKey: base.aggregateKey }
        : {}),
    });
  }
  return [...effective.values()];
}
