export function formatMutationMessage(key: string, data: Record<string, number | string>): string {
  if (!game) {
    throw new Error("Foundry game global is unavailable while formatting a mutation message.");
  }

  return game.i18n.format(`FVTT_WFRP_RATTER.Mutations.${key}`, data);
}

export async function postMutationMessage(content: string): Promise<void> {
  if (!game) {
    throw new Error("Foundry game global is unavailable while posting a mutation message.");
  }

  try {
    const messageData = ChatMessage.applyMode(
      {
        author: game.user.id,
        content,
      },
      "gm",
    );
    await ChatMessage.create(messageData);
  } catch (error) {
    console.error(
      "The Mutant's Handbook workflow could not create an informational message.",
      error,
    );
  }
}

export function warnAboutMutation(content: string): void {
  ui.notifications.warn(content);
}

export function reportMutationError(error: unknown): void {
  const detail = error instanceof Error ? error.message : String(error);
  const message = game
    ? game.i18n.format("FVTT_WFRP_RATTER.Mutations.Error", { message: detail })
    : `The Mutant's Handbook mutation workflow failed: ${detail}`;

  console.error(error);
  ui.notifications.error(message);
}
