import type {
  CharacteristicBonuses,
  HandbookSpecies,
  MutationCounts,
  MutationNature,
  MutationSeverity,
} from "../../types/mutants-handbook";

const SPECIES_ALIASES: Readonly<Record<string, HandbookSpecies>> = {
  "dwarf": "dwarf",
  "elf": "elf",
  "gnome": "gnome",
  "halfling": "halfling",
  "helf": "elf",
  "high elf": "elf",
  "high-elf": "elf",
  "human": "human",
  "ogre": "ogre",
  "welf": "elf",
  "wood elf": "elf",
  "wood-elf": "elf",
};

export function resolveHandbookSpecies(value: string): HandbookSpecies | undefined {
  return SPECIES_ALIASES[value.trim().toLowerCase()];
}

export function resolveMutationNature(value: string): MutationNature | undefined {
  const normalizedValue = value.trim().toLowerCase();

  if (normalizedValue.startsWith("physical")) {
    return "physical";
  }

  if (normalizedValue.startsWith("mental")) {
    return "mental";
  }

  return undefined;
}

export function resolveMutationSeverity(value: string): MutationSeverity | undefined {
  const normalizedValue = value.trim().toLowerCase();

  if (normalizedValue.startsWith("trivial")) {
    return "trivial";
  }

  if (normalizedValue.startsWith("minor")) {
    return "minor";
  }

  if (normalizedValue.startsWith("major")) {
    return "major";
  }

  if (normalizedValue.includes("chosen")) {
    return "chosen";
  }

  return undefined;
}

export function getSeverityModifier(mutationCount: number): number {
  const count = Math.max(0, Math.floor(mutationCount));
  return Math.min(count, 4) * 10;
}

export function getCorruptionLoss(nature: MutationNature, bonuses: CharacteristicBonuses): number {
  return nature === "physical" ? bonuses.toughness : bonuses.willpower;
}

export function getReducedCorruption(current: number, loss: number): number {
  return Math.max(0, current - Math.max(0, loss));
}

export function countMutationNatures(natures: readonly string[]): MutationCounts {
  let mental = 0;
  let physical = 0;

  for (const value of natures) {
    const nature = resolveMutationNature(value);

    if (nature === "mental") {
      mental += 1;
    } else if (nature === "physical") {
      physical += 1;
    }
  }

  return {
    mental,
    physical,
    total: natures.length,
  };
}

export function getChaosSpawnNatures(
  counts: MutationCounts,
  bonuses: CharacteristicBonuses,
): MutationNature[] {
  const exceeded: MutationNature[] = [];

  if (counts.physical > bonuses.toughness) {
    exceeded.push("physical");
  }

  if (counts.mental > bonuses.willpower) {
    exceeded.push("mental");
  }

  return exceeded;
}
