import { countMutationNatures } from "../../../functions/mutants-handbook/rules";
import type { WfrpActor } from "../../../types/foundry";
import type { ChosenPatron, MutationCounts } from "../../../types/mutants-handbook";
import { MODULE_ID } from "../../constants";
import {
  CHAOS_SPAWN_FLAG,
  CHOSEN_PATRON_FLAG,
  MUTATION_RETIRED_FLAG,
  POSSESSION_REMOVED_FLAG,
} from "./constants";
import { activeMutations, isMutationRetired, normalizeName } from "./document-helpers";

const CHAOS_PATRONS: ChosenPatron[] = ["khorne", "nurgle", "slaanesh", "tzeentch", "unassigned"];

export function isWfrpActor(document: unknown): document is WfrpActor {
  if (typeof document !== "object" || document === null) return false;

  const actor = document as Partial<WfrpActor>;
  return (
    actor.type === "character" &&
    typeof actor.name === "string" &&
    typeof actor.uuid === "string" &&
    typeof actor.createEmbeddedDocuments === "function" &&
    typeof actor.deleteEmbeddedDocuments === "function" &&
    typeof actor.getFlag === "function" &&
    typeof actor.has === "function" &&
    typeof actor.setupCharacteristic === "function" &&
    typeof actor.setupSkill === "function" &&
    typeof actor.update === "function" &&
    typeof actor.updateEmbeddedDocuments === "function"
  );
}

export function getMutationCounts(actor: WfrpActor): MutationCounts {
  const isChosen = getChosenPatron(actor) !== undefined;
  const natures = (actor.itemTypes.mutation ?? [])
    .filter(
      (item) => !isMutationRetired(item) && !(isChosen && normalizeName(item.name) === "possessed"),
    )
    .map((item) => item.system.mutationType.value);
  return countMutationNatures(natures);
}

export function getChosenPatron(actor: WfrpActor): ChosenPatron | undefined {
  const value = actor.getFlag(MODULE_ID, CHOSEN_PATRON_FLAG);
  return CHAOS_PATRONS.find((patron) => patron === value);
}

export function hasPossessedMutation(actor: WfrpActor): boolean {
  return (actor.itemTypes.mutation ?? []).some(
    (item) => normalizeName(item.name) === "possessed" && !isMutationRetired(item),
  );
}

export function hasMutationNamed(actor: WfrpActor, name: string): boolean {
  const normalizedName = normalizeName(name);
  return (actor.itemTypes.mutation ?? []).some(
    (item) => normalizeName(item.name) === normalizedName && !isMutationRetired(item),
  );
}

export function isHandbookChaosSpawn(actor: WfrpActor): boolean {
  return actor.getFlag(MODULE_ID, CHAOS_SPAWN_FLAG) === true;
}

export async function retirePossessedMutations(actor: WfrpActor): Promise<void> {
  const updates = (actor.itemTypes.mutation ?? [])
    .filter((item) => normalizeName(item.name) === "possessed" && !isMutationRetired(item))
    .map((item) => ({
      _id: item.id,
      [`flags.${MODULE_ID}.${POSSESSION_REMOVED_FLAG}`]: true,
    }));

  if (updates.length === 0) return;
  const updatedItems = await actor.updateEmbeddedDocuments("Item", updates);
  if (updatedItems.length !== updates.length) {
    throw new Error(`Foundry prevented Possessed from being retired for ${actor.name}.`);
  }
}

export async function retireSkinwalkerMutations(actor: WfrpActor): Promise<string[]> {
  const mutations = activeMutations(actor).filter(
    (item) => normalizeName(item.name) === "skinwalker",
  );
  if (mutations.length === 0) return [];
  const updatedItems = await actor.updateEmbeddedDocuments(
    "Item",
    mutations.map((item) => ({
      _id: item.id,
      [`flags.${MODULE_ID}.${MUTATION_RETIRED_FLAG}`]: true,
    })),
  );
  if (updatedItems.length !== mutations.length) {
    const updatedIds = new Set(updatedItems.map((item) => item.id));
    const partiallyRetired = mutations
      .filter((item) => updatedIds.has(item.id))
      .map((item) => item.id);
    try {
      await restoreRetiredMutations(actor, partiallyRetired);
    } catch (error) {
      throw new AggregateError(
        [error],
        `Foundry only partially retired Skinwalker for ${actor.name}, and rollback failed.`,
        { cause: error },
      );
    }
    throw new Error(`Foundry prevented Skinwalker from being retired for ${actor.name}.`);
  }
  return mutations.map((item) => item.id);
}

export async function restoreRetiredMutations(
  actor: WfrpActor,
  mutationIds: readonly string[],
): Promise<void> {
  if (mutationIds.length === 0) return;
  const updatedItems = await actor.updateEmbeddedDocuments(
    "Item",
    mutationIds.map((id) => ({
      _id: id,
      [`flags.${MODULE_ID}.-=${MUTATION_RETIRED_FLAG}`]: null,
    })),
  );
  if (updatedItems.length !== mutationIds.length) {
    throw new Error(`Foundry prevented retired mutations from being restored for ${actor.name}.`);
  }
}
