import type { ModuleApi } from "../../types/module/api/ModuleApi";
import { MODULE_ID, MODULE_TITLE } from "../constants";
import { checkMutantsHandbookCorruptionByUuid } from "../wfrp4e/mutants-handbook/check";
import {
  reconcileMutationAutomation,
  removeMutationGrantOwner,
} from "../wfrp4e/mutants-handbook/automation/grant-reconciliation";
import {
  applyMutationActionOutcome,
  prepareMutationActionDialog,
  recordMutationActionUse,
  resolveMutationActionTest,
  useMutationAction,
} from "../wfrp4e/mutants-handbook/actions";

export function createModuleApi(): ModuleApi {
  return {
    applyMutationActionOutcome,
    checkMutantsHandbookCorruption: checkMutantsHandbookCorruptionByUuid,
    id: MODULE_ID,
    logStatus() {
      console.log(`${MODULE_TITLE} is loaded.`);
    },
    prepareMutationActionDialog,
    recordMutationActionUse,
    reconcileMutationAutomation,
    removeMutationGrantOwner,
    resolveMutationActionTest,
    title: MODULE_TITLE,
    useMutationAction,
  };
}
