import type { WfrpActor } from "../../../../../types/foundry";
import { MODULE_ID } from "../../../../constants";
import {
  getGrantOwnership,
  getLegacyGrantOwners,
  getSkillGrantLedger,
  isLegacyManagedGrant,
} from "../grant-data";
import { actorItems, updateItem } from "./helpers";

export interface ExpectedGrant {
  itemId?: string;
  signature: string;
}

export async function cleanOwnerReferences(
  actor: WfrpActor,
  ownerId: string,
  expected: ReadonlyMap<string, ExpectedGrant>,
): Promise<void> {
  const deleteIds: string[] = [];

  for (const item of actorItems(actor)) {
    const ownership = getGrantOwnership(item);
    const legacyOwners = getLegacyGrantOwners(item);
    const owners = (ownership?.owners ?? []).filter((owner) => {
      if (owner.ownerId !== ownerId) return true;
      const target = expected.get(owner.grantKey);
      return (
        target !== undefined &&
        target.signature === ownership?.signature &&
        (target.itemId === undefined || target.itemId === item.id)
      );
    });
    const expectedTargets = [...expected.values()];
    const selectedLegacyItem = expectedTargets.some((target) => target.itemId === item.id);
    const unavailableExpectedGrant = expectedTargets.some((target) => target.itemId === undefined);
    const remainingLegacyOwners = legacyOwners.filter(
      (legacyOwner) => legacyOwner !== ownerId || selectedLegacyItem || unavailableExpectedGrant,
    );
    const changed =
      owners.length !== (ownership?.owners.length ?? 0) ||
      remainingLegacyOwners.length !== legacyOwners.length;
    if (!changed) continue;

    const managed = ownership?.managed ?? isLegacyManagedGrant(item);
    if (
      managed &&
      owners.length === 0 &&
      remainingLegacyOwners.length === 0 &&
      !getSkillGrantLedger(item)
    ) {
      deleteIds.push(item.id);
      continue;
    }

    const changes: Record<string, unknown> = {};
    if (remainingLegacyOwners.length > 0) {
      changes[`flags.${MODULE_ID}.mutationGrantOwners`] = remainingLegacyOwners;
      if (isLegacyManagedGrant(item)) {
        changes[`flags.${MODULE_ID}.mutationGrantManaged`] = true;
      }
    } else {
      changes[`flags.${MODULE_ID}.-=mutationGrantManaged`] = null;
      changes[`flags.${MODULE_ID}.-=mutationGrantOwners`] = null;
    }
    if (ownership && owners.length > 0) {
      changes[`flags.${MODULE_ID}.mutationGrant`] = { ...ownership, owners };
    } else if (ownership) {
      changes[`flags.${MODULE_ID}.-=mutationGrant`] = null;
    }
    await updateItem(actor, item, changes);
  }

  if (deleteIds.length > 0) {
    await actor.deleteEmbeddedDocuments("Item", deleteIds);
  }
}
